  ledger_name text not null,
  ledger_group text,
  tax_head text,                         -- IGST, CGST, SGST, CESS
  period date,
  opening numeric(18,2) not null default 0,
  debit numeric(18,2) not null default 0,
  credit numeric(18,2) not null default 0,
