insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"b4766868-cfb2-471d-b71c-4e6f53172e1b","code":"CGST-ACT-S13","source_type":"act","title":"Time of supply of services","provision":"Section 13","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Time of supply of services is generally the earlier of the date of invoice (if issued within the prescribed period) and date of receipt of payment, with specific rules for reverse charge and associated enterprises.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.959732+00:00","updated_at":"2026-10-24T13:42:07.959732+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"3cf33ad2-a0e6-4760-a9b6-0fefd1b76488","code":"CGST-ACT-S13-3","source_type":"act","title":"Time of supply of services under reverse charge","provision":"Section 13(3)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"For services taxable under reverse charge, time of supply is the earlier of the date of payment and the date immediately following sixty days from the supplier''s invoice; for associated enterprises located outside India, it is the earlier of date of entry in the books of the recipient and date of payment.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.96224+00:00","updated_at":"2026-10-24T13:42:07.96224+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"9e46c98e-ea89-45da-9742-a90dbd9021ca","code":"CGST-ACT-S15","source_type":"act","title":"Value of taxable supply","provision":"Section 15","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Value of supply is the transaction value where supplier and recipient are not related and price is the sole consideration; otherwise value is determined under the valuation rules.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.964014+00:00","updated_at":"2026-10-24T13:42:07.964014+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"75e6efef-420e-4a40-9b82-013ebb0641f5","code":"CGST-ACT-S107","source_type":"act","title":"Appeals to Appellate Authority","provision":"Section 107","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Appeal against an order may be filed within three months from communication (condonable by one further month), subject to mandatory pre-deposit of admitted tax and 10% of the disputed tax subject to the statutory monetary cap; filing with pre-deposit stays recovery of the balance.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.050962+00:00","updated_at":"2026-10-24T13:42:08.050962+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"6b38410e-1d22-4e93-b3b1-1a2e9531d323","code":"CGST-ACT-S15-2","source_type":"act","title":"Inclusions in value of supply","provision":"Section 15(2)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Value includes taxes other than GST charged separately, amounts the supplier is liable to pay but incurred by the recipient, incidental expenses such as commission and packing, interest/late fee/penalty for delayed payment, and subsidies directly linked to price (excluding Government subsidies).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.965625+00:00","updated_at":"2026-10-24T13:42:07.965625+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d3a28bce-a24d-4a97-9434-aafbeb029b6a","code":"CGST-ACT-S15-3","source_type":"act","title":"Discounts excluded from value of supply","provision":"Section 15(3)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Discount given before or at the time of supply and recorded in the invoice is excluded from value. Post-supply discount is excluded only if established by an agreement entered into before or at the time of supply, specifically linked to relevant invoices, and the recipient has reversed the attributable input tax credit.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.969288+00:00","updated_at":"2026-10-24T13:42:07.969288+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"9477e7f8-bf5b-453f-855c-dd736a820e41","code":"CGST-ACT-S16-1","source_type":"act","title":"Eligibility for input tax credit","provision":"Section 16(1)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"A registered person is entitled to credit of input tax charged on supply of goods or services used or intended to be used in the course or furtherance of business, subject to prescribed conditions and restrictions.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.97187+00:00","updated_at":"2026-10-24T13:42:07.97187+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d1033abc-dc3e-404b-a984-2e09991cbfae","code":"CGST-ACT-S16-2","source_type":"act","title":"Conditions for availing input tax credit","provision":"Section 16(2)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"ITC is available only if the recipient holds a tax invoice/debit note, the details are furnished by the supplier and communicated (clause (aa)), goods or services have been received (including bill-to-ship-to), tax has been actually paid to the Government by the supplier, and the recipient has furnished its return. Credit is to be reversed if the supplier is not paid within 180 days.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.975193+00:00","updated_at":"2026-10-24T13:42:07.975193+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"575e795c-ca38-422b-9917-cfb333ab20ef","code":"CGST-ACT-S16-2-AA","source_type":"act","title":"ITC restricted to details communicated in GSTR-2B","provision":"Section 16(2)(aa)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2022-01-01","effective_to":null,"applicable_fys":[],"summary":"Inserted with effect from 01.01.2022, ITC is available only where the supplier has furnished the invoice/debit note in its outward statement and such details are communicated to the recipient (GSTR-2B).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.976808+00:00","updated_at":"2026-10-24T13:42:07.976808+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"6bafa60a-4aef-487c-8160-27ff3ee5af91","code":"CGST-ACT-S16-3","source_type":"act","title":"No ITC on tax component claimed as depreciation","provision":"Section 16(3)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Where depreciation has been claimed under the Income-tax Act on the tax component of the cost of capital goods and plant and machinery, ITC on that tax component is not allowed.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.978136+00:00","updated_at":"2026-10-24T13:42:07.978136+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"fa3ab8aa-fa83-4d36-ba38-ff97a9749c31","code":"CGST-ACT-S16-4","source_type":"act","title":"Time limit for availing input tax credit","provision":"Section 16(4)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"ITC in respect of an invoice or debit note cannot be availed after the thirtieth day of November following the end of the financial year to which it pertains, or the date of furnishing the relevant annual return, whichever is earlier. The 30 November cut-off applies as amended with effect from 01.10.2022 (earlier: due date of September return).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.98004+00:00","updated_at":"2026-10-24T13:42:07.98004+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"897d245b-1e6a-4f2b-8eb1-9be23b93ff74","code":"CGST-ACT-S16-5","source_type":"act","title":"Extended time limit for FY 2017-18 to 2020-21","provision":"Section 16(5)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Inserted by the Finance (No. 2) Act, 2024 with retrospective effect, permits ITC for FY 2017-18 to FY 2020-21 availed in any return filed up to 30 November 2021, notwithstanding Section 16(4).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.981539+00:00","updated_at":"2026-10-24T13:42:07.981539+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"43734a46-98c5-4468-9f5b-1fa7961d84ad","code":"CGST-ACT-S17-2","source_type":"act","title":"Apportionment of credit for business and exempt use","provision":"Section 17(1)-(2)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Where goods or services are used partly for business and partly for other purposes, or partly for taxable and partly for exempt supplies (including non-taxable supplies), credit is restricted to the portion attributable to business and taxable/zero-rated supplies, computed under Rules 42 and 43.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.983599+00:00","updated_at":"2026-10-24T13:42:07.983599+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"b4b6338d-4d05-44c2-a919-e1cd657ae18b","code":"CGST-ACT-S17-5","source_type":"act","title":"Blocked input tax credit","provision":"Section 17(5)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Lists credits not available, including motor vehicles and conveyances (with exceptions), food and beverages, outdoor catering, beauty treatment, health services, life and health insurance, club membership, travel benefits to employees (unless obligatory under law), works contract and construction of immovable property (other than plant and machinery), goods lost/stolen/destroyed/written off or disposed by way of gift or free samples, and tax paid under Sections 74, 129 and 130.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.985454+00:00","updated_at":"2026-10-24T13:42:07.985454+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d5f159cc-29fe-43e7-a782-c7eae0ef8c6c","code":"CGST-ACT-S18-1","source_type":"act","title":"ITC on new registration and changes in scheme","provision":"Section 18(1)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Provides credit on stock held on the day preceding the date of becoming liable to register or obtaining registration, subject to conditions and a one-year time limit from the invoice date.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.987276+00:00","updated_at":"2026-10-24T13:42:07.987276+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"1e73a9d8-8414-4dac-9397-a7bb462d7876","code":"CGST-ACT-S18-3","source_type":"act","title":"Transfer of ITC on change in constitution or business transfer","provision":"Section 18(3)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Where there is a change in constitution of a registered person on account of sale, merger, demerger, amalgamation, lease or transfer of business with specific provision for transfer of liabilities, the unutilised ITC may be transferred to the transferee in the prescribed manner (Form GST ITC-02).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.989133+00:00","updated_at":"2026-10-24T13:42:07.989133+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"3c3a0f54-a5b7-4888-b4b0-0559b7cfa89f","code":"CGST-ACT-S18-6","source_type":"act","title":"Supply of capital goods on which ITC has been taken","provision":"Section 18(6)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"On supply of capital goods or plant and machinery on which ITC has been taken, the registered person shall pay an amount equal to the ITC taken reduced by the prescribed percentage points, or the tax on transaction value, whichever is higher. Refractory bricks, moulds and dies, jigs and fixtures supplied as scrap may pay tax on transaction value.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.992149+00:00","updated_at":"2026-10-24T13:42:07.992149+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"2f93f55a-805a-49fd-b058-03bf846bf5f8","code":"CGST-ACT-S19","source_type":"act","title":"ITC on inputs and capital goods sent for job work","provision":"Section 19","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Principal may avail ITC on inputs and capital goods sent to a job worker; if inputs are not received back within one year, or capital goods within three years (other than moulds, dies, jigs, fixtures and tools), they are deemed supplied on the day they were sent out.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.993922+00:00","updated_at":"2026-10-24T13:42:07.993922+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"8f1f4e29-92dd-4dc8-9809-8631453aca9f","code":"CGST-ACT-S20","source_type":"act","title":"Manner of distribution of credit by Input Service Distributor","provision":"Section 20","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2025-04-01","effective_to":null,"applicable_fys":[],"summary":"As substituted with effect from 01.04.2025, any office receiving invoices for input services, including services subject to reverse charge, for or on behalf of distinct persons is required to register as an ISD and distribute such credit in the prescribed manner.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.99532+00:00","updated_at":"2026-10-24T13:42:07.99532+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"2e5938ac-7f2e-4057-b4ce-fd38df203414","code":"CGST-ACT-S22","source_type":"act","title":"Persons liable for registration","provision":"Section 22","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Every supplier whose aggregate turnover in a financial year exceeds the threshold (Rs 20 lakh / Rs 10 lakh for special category States; Rs 40 lakh for exclusive goods suppliers in States that have adopted it) is liable to register in each State/UT from which taxable supply is made.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.996766+00:00","updated_at":"2026-10-24T13:42:07.996766+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"e5a9f892-54bd-400b-bb99-b910c4fff587","code":"CGST-ACT-S24","source_type":"act","title":"Compulsory registration in certain cases","provision":"Section 24","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Specified persons must register irrespective of turnover, including inter-State taxable suppliers (subject to exemptions), persons liable under reverse charge, ECOs, TDS deductors, ISDs, and non-resident taxable persons.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.998027+00:00","updated_at":"2026-10-24T13:42:07.998027+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"ae8e8337-985c-4e48-b7d4-a80a30bfd6c6","code":"CGST-ACT-S25","source_type":"act","title":"Procedure for registration","provision":"Section 25","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Registration is required in every State/UT where the person is liable, within 30 days; separate registrations may be obtained for each place of business. Establishments with separate registrations are treated as distinct persons (Section 25(4)).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:07.999377+00:00","updated_at":"2026-10-24T13:42:07.999377+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"634afb07-99a1-4cff-a7cc-0efb835f26f2","code":"CGST-ACT-S25-4","source_type":"act","title":"Distinct persons","provision":"Section 25(4)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"A person who has obtained or is required to obtain more than one registration, in one or more States, is treated as a distinct person in respect of each such registration.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.001193+00:00","updated_at":"2026-10-24T13:42:08.001193+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"f085be63-0386-41fe-99cc-67c08ee48e1b","code":"CGST-ACT-S28","source_type":"act","title":"Amendment of registration","provision":"Section 28","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Every registered person shall inform the proper officer of any change in the information furnished at the time of registration, including addition of places of business, within the prescribed period (Rule 19: 15 days).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.003113+00:00","updated_at":"2026-10-24T13:42:08.003113+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"7978b42d-3162-4690-b364-a68506ce133e","code":"CGST-ACT-S29","source_type":"act","title":"Cancellation or suspension of registration","provision":"Section 29","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Provides for cancellation of registration on application or by the proper officer for non-compliance, including non-filing of returns, and for suspension pending proceedings.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.004837+00:00","updated_at":"2026-10-24T13:42:08.004837+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"96df5aef-edc1-454c-8296-835dbd4715e8","code":"CGST-ACT-S31","source_type":"act","title":"Tax invoice","provision":"Section 31","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"A registered person supplying goods or services must issue a tax invoice within the prescribed time containing prescribed particulars; separate provisions govern bills of supply, receipt vouchers, refund vouchers and payment vouchers.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.006454+00:00","updated_at":"2026-10-24T13:42:08.006454+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"392a1db5-6c37-47f1-bba3-72dce43fd111","code":"CGST-ACT-S31-3-F","source_type":"act","title":"Self-invoice and payment voucher for reverse charge","provision":"Section 31(3)(f)-(g)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"A registered person liable to pay tax under Section 9(3) or 9(4) on supplies from an unregistered supplier must issue an invoice in respect of such goods or services, and a payment voucher at the time of making payment to the supplier.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.008535+00:00","updated_at":"2026-10-24T13:42:08.008535+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"3bc150a8-cdf7-4a7e-ba43-5ef060c2d43c","code":"CGST-ACT-S34","source_type":"act","title":"Credit and debit notes","provision":"Section 34","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Credit notes may be issued where taxable value or tax in an invoice exceeds the actual value, goods are returned, or services are found deficient. Details of a credit note must be declared not later than 30 November following the end of the financial year of the supply or the date of furnishing the annual return, whichever is earlier, and output tax reduction is not permitted if the incidence has been passed on.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.010058+00:00","updated_at":"2026-10-24T13:42:08.010058+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"167a7258-9d6a-449b-994a-9394145860d1","code":"CGST-ACT-S35","source_type":"act","title":"Accounts and other records","provision":"Section 35","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Every registered person shall keep and maintain at the principal place of business true and correct accounts of production, inward and outward supplies, stock, ITC availed, output tax payable and paid, and other prescribed particulars, for each place of business.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.011498+00:00","updated_at":"2026-10-24T13:42:08.011498+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"91bda07d-f8a6-4043-86a4-4bafa8bcc6d5","code":"CGST-ACT-S36","source_type":"act","title":"Period of retention of accounts","provision":"Section 36","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Accounts and records shall be retained until the expiry of 72 months from the due date of furnishing the annual return for the year to which they pertain; longer if subject to appeal, revision, or other proceedings.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.013017+00:00","updated_at":"2026-10-24T13:42:08.013017+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d7263766-34bf-445e-a4e3-88be0a7e1ee6","code":"CGST-ACT-S37","source_type":"act","title":"Furnishing details of outward supplies (GSTR-1)","provision":"Section 37","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Every registered person shall furnish details of outward supplies in the prescribed form (GSTR-1) for each tax period; details cannot be furnished after the expiry of three years from the due date, and are subject to prescribed restrictions.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.014591+00:00","updated_at":"2026-10-24T13:42:08.014591+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"01ffffa2-d8f6-45ce-a309-8d24cce5ffa1","code":"CGST-ACT-S39","source_type":"act","title":"Furnishing of returns (GSTR-3B)","provision":"Section 39","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Every registered person shall furnish a return for each tax period with details of inward and outward supplies, ITC availed, tax payable and tax paid, and shall pay the tax due not later than the last date for furnishing the return.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.016376+00:00","updated_at":"2026-10-24T13:42:08.016376+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"cf521834-38e4-4c29-8a1a-1e9ac7245362","code":"CGST-ACT-S44","source_type":"act","title":"Annual return","provision":"Section 44","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Every registered person (other than notified exceptions) shall furnish an annual return for each financial year, with a self-certified reconciliation statement for notified classes, by 31 December following the end of the financial year.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.018262+00:00","updated_at":"2026-10-24T13:42:08.018262+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"df4b7195-3e3e-45ea-b397-f459d657497e","code":"CGST-ACT-S47","source_type":"act","title":"Levy of late fee","provision":"Section 47","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Late fee is payable for delayed furnishing of returns including GSTR-1, GSTR-3B and the annual return, at rates and subject to caps as notified by the Government.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.021169+00:00","updated_at":"2026-10-24T13:42:08.021169+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"7a17b540-7db0-4d8e-863e-8b7c6e94a704","code":"CGST-ACT-S49","source_type":"act","title":"Payment of tax, interest, penalty and other amounts","provision":"Section 49","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Payments are credited to the electronic cash ledger and ITC to the electronic credit ledger; credit may be used only for output tax. Reverse-charge tax, interest, penalty and late fee are payable through the cash ledger. Balance in the cash ledger may be refunded under Section 54.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.025404+00:00","updated_at":"2026-10-24T13:42:08.025404+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"91dda0d4-a967-4d64-b3fa-cc529d3342a5","code":"CGST-ACT-S49A","source_type":"act","title":"Utilisation of input tax credit subject to certain conditions","provision":"Section 49A","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2019-02-01","effective_to":null,"applicable_fys":[],"summary":"IGST credit must be fully utilised towards IGST, CGST and SGST liability before CGST or SGST credit is utilised; read with Rule 88A on the order of utilisation.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.027665+00:00","updated_at":"2026-10-24T13:42:08.027665+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"5424f48c-3e58-45ed-b9a1-66cd0ca6106f","code":"CGST-ACT-S50-1","source_type":"act","title":"Interest on delayed payment of tax","provision":"Section 50(1)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Interest at the notified rate (18% p.a.) is payable on tax not paid within the due period; interest on delayed payment of tax declared in a return filed after the due date is levied on the portion paid by debiting the electronic cash ledger, except where the return is filed after commencement of proceedings under Sections 73/74.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.029578+00:00","updated_at":"2026-10-24T13:42:08.029578+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"dde0fae8-097e-4492-b744-75f5fca8a8e8","code":"CGST-ACT-S50-3","source_type":"act","title":"Interest on ITC wrongly availed and utilised","provision":"Section 50(3)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Interest at the notified rate (18% p.a.) is payable where ITC has been wrongly availed and utilised, computed in the prescribed manner (Rule 88B). Mere availment without utilisation does not attract interest. The substituted provision applies retrospectively from 01.07.2017.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.031363+00:00","updated_at":"2026-10-24T13:42:08.031363+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"eb9972cf-eabb-49d5-a985-11766bf4ef4d","code":"CGST-ACT-S51","source_type":"act","title":"Tax deduction at source","provision":"Section 51","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2018-10-01","effective_to":null,"applicable_fys":[],"summary":"Notified Government departments, local authorities, agencies and other notified persons deduct TDS at 2% (1% CGST + 1% SGST, or 2% IGST) on payments to suppliers of taxable goods or services where the contract value exceeds Rs 2.5 lakh, and file GSTR-7; the deductee may claim the credit in its electronic cash ledger.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.03317+00:00","updated_at":"2026-10-24T13:42:08.03317+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"18b1ecd1-a700-42ef-92c7-17b372016ccc","code":"CGST-ACT-S52","source_type":"act","title":"Collection of tax at source by e-commerce operator","provision":"Section 52","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2018-10-01","effective_to":null,"applicable_fys":[],"summary":"Every electronic commerce operator not being an agent shall collect tax at the notified rate on the net value of taxable supplies made through it by other suppliers where consideration is collected by the operator, and furnish GSTR-8; suppliers claim the amount in their electronic cash ledger.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.035269+00:00","updated_at":"2026-10-24T13:42:08.035269+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"9be5a6a5-401d-412e-bd9f-ce1e06dde0c3","code":"CGST-ACT-S54","source_type":"act","title":"Refund of tax","provision":"Section 54","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Refund of tax, interest or other amounts may be claimed within two years from the relevant date; refund of unutilised ITC is permitted for zero-rated supplies without payment of tax and for inverted duty structure, subject to conditions. Balance in electronic cash ledger may be refunded as prescribed.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.037316+00:00","updated_at":"2026-10-24T13:42:08.037316+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"22a62a86-7cc2-4655-87ef-331d7d9d966b","code":"CGST-ACT-S61","source_type":"act","title":"Scrutiny of returns","provision":"Section 61","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"The proper officer may scrutinise returns and inform discrepancies (Form ASMT-10) seeking explanation; if the explanation is accepted no further action is taken, otherwise action may be initiated including audit, special audit, or demand proceedings.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.038861+00:00","updated_at":"2026-10-24T13:42:08.038861+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"f7f38418-6ecd-4bfa-9239-178a0601b670","code":"CGST-ACT-S65","source_type":"act","title":"Audit by tax authorities","provision":"Section 65","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"The Commissioner may undertake audit of a registered person with prior notice (Form ADT-01); audit is to be completed within three months (extendable by six months), and findings are communicated in Form ADT-02.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.040337+00:00","updated_at":"2026-10-24T13:42:08.040337+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"bbbb0258-12ed-4fbb-9ccc-5487477218ad","code":"CGST-ACT-S73","source_type":"act","title":"Determination of tax not paid or ITC wrongly availed (non-fraud)","provision":"Section 73","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Governs demands for tax not paid, short paid, erroneously refunded or ITC wrongly availed or utilised for reasons other than fraud, wilful misstatement or suppression, for periods up to FY 2023-24. Order must be issued within three years from the due date of the annual return; no penalty if tax and interest are paid before notice, and reduced exposure if paid within 30 days of notice.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.041592+00:00","updated_at":"2026-10-24T13:42:08.041592+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"a90cd7cb-60c8-40f8-b509-b808f7d7b9d3","code":"CGST-ACT-S74","source_type":"act","title":"Determination of tax not paid or ITC wrongly availed (fraud/suppression)","provision":"Section 74","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Governs demands involving fraud, wilful misstatement or suppression of facts for periods up to FY 2023-24, with an extended limitation of five years from the due date of the annual return and penalty equal to the tax (reduced if paid at earlier stages). ITC on tax paid under Section 74 is blocked by Section 17(5).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.043023+00:00","updated_at":"2026-10-24T13:42:08.043023+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"566d8134-f20d-4482-84bc-0052632bd0c1","code":"CGST-ACT-S74A","source_type":"act","title":"Determination of tax for FY 2024-25 onwards","provision":"Section 74A","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2024-11-01","effective_to":null,"applicable_fys":[],"summary":"Inserted by the Finance (No. 2) Act, 2024, provides a common procedure for demands relating to FY 2024-25 onwards, both fraud and non-fraud. Notice is to be issued within 42 months from the due date of annual return (or date of erroneous refund) and the order within 12 months of notice, extendable; penalty differs for fraud and non-fraud cases.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.044776+00:00","updated_at":"2026-10-24T13:42:08.044776+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"07435b82-8026-4b1c-8eda-ced0d2a5f708","code":"CGST-ACT-S75","source_type":"act","title":"General provisions relating to determination of tax","provision":"Section 75","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Lays down procedural safeguards in demand proceedings including opportunity of personal hearing where requested or adverse decision contemplated, a maximum of three adjournments, and that demand cannot exceed the amount specified in the notice or be confirmed on grounds not in the notice.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.047284+00:00","updated_at":"2026-10-24T13:42:08.047284+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d4d679dc-3f06-4083-be9b-97fb46b5741a","code":"CGST-ACT-S77","source_type":"act","title":"Tax wrongfully collected and paid to Central/State Government","provision":"Section 77","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Where a person has paid CGST/SGST on a transaction considered intra-State that is subsequently held to be inter-State (or vice versa), the tax paid under the wrong head is refunded and the person is not required to pay interest on the amount payable under the correct head.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.049218+00:00","updated_at":"2026-10-24T13:42:08.049218+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"ae35bdfe-07a0-4cde-9e85-e437c184c822","code":"CGST-ACT-S122","source_type":"act","title":"Penalty for certain offences","provision":"Section 122","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Prescribes penalties for specified offences, including supply without invoice or with incorrect invoice, issuing invoice without supply, failing to deduct or collect tax, availing ITC without receipt of goods or services, and transporting goods without prescribed documents.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.056179+00:00","updated_at":"2026-10-24T13:42:08.056179+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d0e486e4-eeeb-48b3-be5b-d504d1cde2f0","code":"CGST-ACT-S125","source_type":"act","title":"General penalty","provision":"Section 125","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Any contravention for which no separate penalty is provided is liable to a penalty which may extend to Rs 25,000.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.058868+00:00","updated_at":"2026-10-24T13:42:08.058868+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"1d472380-6286-4e0d-a092-2680200545b2","code":"CGST-ACT-S128A","source_type":"act","title":"Waiver of interest or penalty for FY 2017-18 to 2019-20","provision":"Section 128A","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2024-11-01","effective_to":null,"applicable_fys":[],"summary":"Inserted by the Finance (No. 2) Act, 2024, provides for waiver of interest and penalty on demands raised under Section 73 for FY 2017-18 to 2019-20 where the full tax demanded is paid by the notified date, subject to conditions and exclusions (e.g., erroneous refunds). Not applicable to Section 74 demands.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.060953+00:00","updated_at":"2026-10-24T13:42:08.060953+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"fed6b424-b31e-4b98-9aa8-ca62414638cf","code":"CGST-ACT-S129","source_type":"act","title":"Detention, seizure and release of goods in transit","provision":"Section 129","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Goods transported in contravention of the Act (including without valid e-way bill) may be detained; release is on payment of penalty (for taxable goods, 200% of the tax payable where the owner comes forward, as amended with effect from 01.01.2022). Tax paid under Section 129 is blocked from ITC.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.062449+00:00","updated_at":"2026-10-24T13:42:08.062449+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"3dfbfc22-dc45-46a8-8b85-995dca487b9c","code":"CGST-ACT-S143","source_type":"act","title":"Job work procedure","provision":"Section 143","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"A principal may send inputs and capital goods to a job worker without payment of tax under intimation; inputs must be returned within one year and capital goods within three years, failing which they are deemed supplied from the date of dispatch. Waste and scrap may be supplied by the job worker or principal.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.064303+00:00","updated_at":"2026-10-24T13:42:08.064303+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"afd82537-bd03-440b-976d-65c13018ec96","code":"CGST-ACT-S147","source_type":"act","title":"Deemed exports","provision":"Section 147","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"The Government may notify supplies of goods as deemed exports where goods supplied do not leave India and payment is received in Indian rupees or convertible foreign exchange.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.066821+00:00","updated_at":"2026-10-24T13:42:08.066821+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"43f76d2e-8448-42d5-af8b-8e9c1d70ba7e","code":"CGST-ACT-S155","source_type":"act","title":"Burden of proof","provision":"Section 155","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Where a person claims eligibility for input tax credit, the burden of proving such claim lies on that person.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.069286+00:00","updated_at":"2026-10-24T13:42:08.069286+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"6f3b6e00-311d-471a-8274-2713c0605dd5","code":"CGST-RULE-19","source_type":"rule","title":"Amendment of registration","provision":"Rule 19","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Changes in particulars furnished in the registration application, including addition, deletion or change of places of business, are to be applied for in Form GST REG-14 within 15 days of the change.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.071862+00:00","updated_at":"2026-10-24T13:42:08.071862+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"3180c33b-e7e4-41db-b206-e191b33bdd09","code":"CGST-RULE-21A","source_type":"rule","title":"Suspension of registration","provision":"Rule 21A","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2019-02-01","effective_to":null,"applicable_fys":[],"summary":"Registration may be suspended pending cancellation proceedings, including where significant differences are found between GSTR-1/GSTR-3B and GSTR-2B; a suspended person cannot make taxable supplies or claim refunds during suspension.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.074226+00:00","updated_at":"2026-10-24T13:42:08.074226+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"017732e9-8343-48af-9981-50735b224d0e","code":"CGST-RULE-28","source_type":"rule","title":"Value of supply between distinct or related persons","provision":"Rule 28","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Value is the open market value, failing which the value of like kind and quality, failing which cost plus 10% or residual method. Where the recipient is eligible for full ITC, the value declared in the invoice is deemed to be the open market value.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.076539+00:00","updated_at":"2026-10-24T13:42:08.076539+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"36de9db1-6176-4712-9a8f-6a30adfefdc9","code":"CGST-RULE-33","source_type":"rule","title":"Value of supply of services as pure agent","provision":"Rule 33","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Expenditure incurred as a pure agent of the recipient is excluded from value only where the supplier acts as pure agent under a contract, the recipient receives and is liable to pay for the supply, the expense is separately indicated in the invoice, and the amount recovered is the actual amount paid.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.077846+00:00","updated_at":"2026-10-24T13:42:08.077846+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"bd4d70b2-2022-456b-ae5d-ff573175e57c","code":"CGST-RULE-36-1","source_type":"rule","title":"Documentary requirements for claiming ITC","provision":"Rule 36(1)","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"ITC may be availed on the basis of tax invoice, debit note, invoice for reverse charge, ISD invoice, or bill of entry or similar document prescribed under the Customs Act for assessment of IGST on imports.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.079611+00:00","updated_at":"2026-10-24T13:42:08.079611+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"244d0f61-c096-4636-84af-fe4b5114ea95","code":"CGST-RULE-36-4","source_type":"rule","title":"ITC restricted to invoices reflected in GSTR-2B","provision":"Rule 36(4)","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2019-10-09","effective_to":null,"applicable_fys":[],"summary":"Introduced with effect from 09.10.2019 with a provisional cushion, and amended with effect from 01.01.2022 to restrict ITC on invoices and debit notes to those reported by suppliers and communicated in GSTR-2B.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.081965+00:00","updated_at":"2026-10-24T13:42:08.081965+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"6bdf0181-668b-4fff-9a78-7805c1a10bf7","code":"CGST-RULE-37","source_type":"rule","title":"Reversal of ITC on non-payment within 180 days","provision":"Rule 37","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Where the recipient fails to pay the supplier the value of supply plus tax within 180 days from the invoice date, the proportionate ITC must be reversed in the return for the period following the 180th day; credit may be re-availed upon payment.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.084498+00:00","updated_at":"2026-10-24T13:42:08.084498+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"586717b3-8d91-431c-b6fc-6837263dd50e","code":"CGST-RULE-37A","source_type":"rule","title":"Reversal of ITC where supplier has not paid tax","provision":"Rule 37A","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2022-10-01","effective_to":null,"applicable_fys":[],"summary":"Where ITC has been availed on invoices reported by the supplier in GSTR-1 but the supplier has not furnished GSTR-3B for the period by 30 September following the end of the financial year, the recipient must reverse the ITC by 30 November; it may be re-availed once the supplier files the return.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.086939+00:00","updated_at":"2026-10-24T13:42:08.086939+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"8873f6d1-6a39-4dad-a168-7cb8a7d563e0","code":"CGST-RULE-39","source_type":"rule","title":"Procedure for distribution of ITC by ISD","provision":"Rule 39","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"ISD credit must be distributed in the same month through an ISD invoice to recipients to whom the input services are attributable, and common credit is distributed pro rata on turnover of the recipients in the relevant State; GSTR-6 is filed monthly.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.08883+00:00","updated_at":"2026-10-24T13:42:08.08883+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"03a1e53b-2f6a-4ce4-8865-b3d86c4e18df","code":"CGST-RULE-41","source_type":"rule","title":"Transfer of credit on sale, merger, amalgamation, lease or transfer of business","provision":"Rule 41","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"The transferor files Form GST ITC-02 with a certificate from a practising chartered/cost accountant where there is a specific provision for transfer of liabilities; the transferee accepts the credit on the portal, and inputs and capital goods must be duly accounted in the transferee''s books.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.092419+00:00","updated_at":"2026-10-24T13:42:08.092419+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"2d53e63d-1bad-44bd-bd04-c682c86ce2eb","code":"CGST-RULE-42","source_type":"rule","title":"ITC reversal for inputs and input services used for exempt/non-business purposes","provision":"Rule 42","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Prescribes the manner of determining and reversing ITC attributable to exempt supplies and non-business use, on a monthly provisional basis and final computation for the financial year by the due date of the September return following the year end, with interest on short reversal.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.094788+00:00","updated_at":"2026-10-24T13:42:08.094788+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"25b96314-28c6-4e08-a881-8821f2780e1b","code":"CGST-RULE-43","source_type":"rule","title":"ITC reversal on capital goods used for exempt/non-business purposes","provision":"Rule 43","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Common credit on capital goods is credited to the electronic credit ledger and attributed to exempt supplies over a useful life of five years (60 months) on a monthly basis in the ratio of exempt turnover to total turnover.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.099559+00:00","updated_at":"2026-10-24T13:42:08.099559+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"a29d33f6-ba4b-4270-8ce8-947fb95457aa","code":"CGST-RULE-44-6","source_type":"rule","title":"Amount payable on supply of capital goods","provision":"Rule 44(6)","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"For the purpose of Section 18(6), ITC involved in the remaining useful life of capital goods is computed by reducing ITC taken by five percentage points for every quarter or part thereof from the date of invoice.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.102831+00:00","updated_at":"2026-10-24T13:42:08.102831+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"3378b12f-8c76-47fa-8c43-93968d273cab","code":"CGST-RULE-45","source_type":"rule","title":"Conditions and restrictions in respect of inputs and capital goods sent to job worker","provision":"Rule 45","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Inputs, semi-finished goods or capital goods are sent to the job worker under a challan; details of challans and goods returned are reported in Form GST ITC-04 at the prescribed frequency.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.10467+00:00","updated_at":"2026-10-24T13:42:08.10467+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"696bbd6f-1ade-4b01-a6b2-c3bc88d61b90","code":"CGST-RULE-46","source_type":"rule","title":"Tax invoice","provision":"Rule 46","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Prescribes particulars of a tax invoice including consecutive serial number unique for a financial year, GSTIN of recipient, HSN/SAC, taxable value, rate and amount of tax, place of supply, and whether tax is payable on reverse charge.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.106258+00:00","updated_at":"2026-10-24T13:42:08.106258+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"add8f7d2-bd15-4f8c-9976-5d70fb8c206a","code":"CGST-RULE-47","source_type":"rule","title":"Time limit for issuing tax invoice for services","provision":"Rule 47","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Invoice for taxable services shall be issued within 30 days from the date of supply (45 days for banking/insurance and certain financial institutions).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.108426+00:00","updated_at":"2026-10-24T13:42:08.108426+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"9a3ab8b8-1e6c-4222-8369-c1ffffe0367a","code":"CGST-RULE-48-4","source_type":"rule","title":"Electronic invoicing (IRN)","provision":"Rule 48(4)","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2020-10-01","effective_to":null,"applicable_fys":[],"summary":"Notified classes of registered persons must prepare invoices and credit/debit notes for B2B supplies and exports by uploading them to the Invoice Registration Portal to obtain an IRN. An invoice issued otherwise than in this manner is not treated as an invoice (Rule 48(5)).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.110174+00:00","updated_at":"2026-10-24T13:42:08.110174+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"7f42ce65-a29a-4172-ad95-5559283c48fb","code":"CGST-RULE-53","source_type":"rule","title":"Revised tax invoice and credit or debit notes","provision":"Rule 53","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Prescribes the particulars of revised invoices and credit/debit notes, including the serial number and date of the corresponding tax invoice.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.112555+00:00","updated_at":"2026-10-24T13:42:08.112555+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"98c098af-3699-4630-9b2a-439e09e6cde3","code":"CGST-RULE-55","source_type":"rule","title":"Transportation of goods without issue of invoice","provision":"Rule 55","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"A delivery challan may be issued for movement of goods for job work, supply of liquid gas where quantity is unknown, transportation for reasons other than supply, and other notified cases.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.114416+00:00","updated_at":"2026-10-24T13:42:08.114416+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"1534e68d-4af9-42c0-b60c-0988511299c0","code":"CGST-RULE-56","source_type":"rule","title":"Maintenance of accounts by registered persons","provision":"Rule 56","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Specifies the accounts to be maintained, including stock of goods, ITC, output tax, advances, and records at each place of business; electronic records must be backed up and authenticated.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.116922+00:00","updated_at":"2026-10-24T13:42:08.116922+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d775c061-0c4f-421a-98e2-86944b20ddfc","code":"CGST-RULE-59","source_type":"rule","title":"Form and manner of furnishing details of outward supplies","provision":"Rule 59","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Prescribes GSTR-1 and the Invoice Furnishing Facility; sub-rule (6) restricts furnishing GSTR-1 where GSTR-3B of earlier periods has not been furnished or where Rule 86B conditions are not met.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.11841+00:00","updated_at":"2026-10-24T13:42:08.11841+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"95d58dc3-267e-418e-bd70-3d421da2c0c2","code":"CGST-RULE-80","source_type":"rule","title":"Annual return","provision":"Rule 80","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Annual return in Form GSTR-9 is to be furnished by 31 December following the end of the financial year; registered persons above the notified turnover threshold also furnish a self-certified reconciliation statement in Form GSTR-9C.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.120253+00:00","updated_at":"2026-10-24T13:42:08.120253+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"609d9efd-c076-451c-b114-c113730ecff3","code":"CGST-RULE-85","source_type":"rule","title":"Electronic liability register","provision":"Rule 85","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"The electronic liability register records all tax, interest, late fee and penalty liabilities of a registered person, discharged by debiting the electronic cash or credit ledger.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.122322+00:00","updated_at":"2026-10-24T13:42:08.122322+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"2c121804-a766-4f6d-8da8-e7e68dab4074","code":"CGST-RULE-86","source_type":"rule","title":"Electronic credit ledger","provision":"Rule 86","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"ITC as self-assessed in the return is credited to the electronic credit ledger and debited on utilisation or refund; the ledger cannot be in negative balance.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.124399+00:00","updated_at":"2026-10-24T13:42:08.124399+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d4984830-10b5-4529-b459-dcf06508a057","code":"CGST-RULE-86A","source_type":"rule","title":"Conditions of use of amount available in electronic credit ledger","provision":"Rule 86A","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2019-12-26","effective_to":null,"applicable_fys":[],"summary":"The Commissioner or authorised officer may disallow debit of credit fraudulently availed or ineligible on specified grounds (e.g., non-existent supplier, goods not received, supplier not having paid tax) for up to one year.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.12634+00:00","updated_at":"2026-10-24T13:42:08.12634+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"2cb169bc-3f7a-4e6b-a1e6-b837ae880ee9","code":"CGST-RULE-86B","source_type":"rule","title":"Restriction on use of ITC to discharge output liability","provision":"Rule 86B","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2021-01-01","effective_to":null,"applicable_fys":[],"summary":"Registered persons with monthly taxable supply value exceeding Rs 50 lakh shall discharge at least 1% of output tax liability in cash, subject to specified exceptions (e.g., income-tax above threshold, refunds, cash payments above 1% cumulatively).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.130623+00:00","updated_at":"2026-10-24T13:42:08.130623+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"f519577d-bf10-44fa-88ec-d0570ec1bd36","code":"CGST-RULE-87","source_type":"rule","title":"Electronic cash ledger","provision":"Rule 87","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Deposits made through challan (PMT-06) are credited to the electronic cash ledger under major and minor heads. Amounts may be transferred between heads and to distinct persons using Form GST PMT-09, and excess balance may be claimed as refund.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.132777+00:00","updated_at":"2026-10-24T13:42:08.132777+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"7ff4e3e0-1a22-4081-81e3-1ff35ae583cb","code":"CGST-RULE-88A","source_type":"rule","title":"Order of utilisation of input tax credit","provision":"Rule 88A","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2019-03-29","effective_to":null,"applicable_fys":[],"summary":"IGST credit shall first be utilised for IGST, and the balance for CGST and SGST in any order, before CGST or SGST credit is utilised; CGST credit cannot be used for SGST and vice versa.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.134537+00:00","updated_at":"2026-10-24T13:42:08.134537+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"2a46d0ee-f191-403b-9407-445d55a20dbb","code":"CGST-RULE-88B","source_type":"rule","title":"Manner of calculating interest on delayed payment of tax and wrongly availed ITC","provision":"Rule 88B","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2022-07-05","effective_to":null,"applicable_fys":[],"summary":"Interest under Section 50(3) on wrongly availed ITC is computed on the amount utilised, from the date of utilisation till reversal/payment; utilisation is deemed when the electronic credit ledger balance falls below the wrongly availed amount.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.136153+00:00","updated_at":"2026-10-24T13:42:08.136153+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"e9efb459-3da1-4322-9d73-3d612e0c3600","code":"CGST-RULE-88C","source_type":"rule","title":"Intimation of difference between liability in GSTR-1 and GSTR-3B","provision":"Rule 88C","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2022-12-26","effective_to":null,"applicable_fys":[],"summary":"Where output tax in GSTR-1 exceeds that paid in GSTR-3B beyond the prescribed limit, the taxpayer receives an intimation in Form DRC-01B and must pay the difference or explain it; non-response blocks furnishing of the next GSTR-1.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.13791+00:00","updated_at":"2026-10-24T13:42:08.13791+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"ccd638d8-e84b-40d7-ac08-9335768e065c","code":"CGST-RULE-88D","source_type":"rule","title":"Intimation of difference between ITC in GSTR-3B and GSTR-2B","provision":"Rule 88D","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2023-08-04","effective_to":null,"applicable_fys":[],"summary":"Where ITC availed in GSTR-3B exceeds ITC available in GSTR-2B beyond the prescribed limit, the taxpayer receives an intimation in Form DRC-01C and must reverse the excess or explain it; non-response blocks furnishing of GSTR-1.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.139362+00:00","updated_at":"2026-10-24T13:42:08.139362+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"36b190a2-0580-48a1-96b4-b9c7691f382f","code":"CGST-RULE-89","source_type":"rule","title":"Application for refund","provision":"Rule 89","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Refund is claimed in Form RFD-01 with prescribed documents, including SEZ endorsement for supplies to SEZ, statements of invoices, and the formula in sub-rule (4) for refund of ITC on zero-rated supplies without payment of tax and sub-rule (5) for inverted duty structure.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.140913+00:00","updated_at":"2026-10-24T13:42:08.140913+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"63336660-3b7f-4848-ac7e-4cff6b705537","code":"CGST-RULE-96","source_type":"rule","title":"Refund of IGST paid on goods exported","provision":"Rule 96","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"The shipping bill filed by an exporter is deemed to be the refund application for IGST paid on export of goods once the export general manifest is filed and a valid GSTR-3B is furnished; GSTR-1 Table 6A details are transmitted to ICEGATE for validation against the shipping bill.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.142364+00:00","updated_at":"2026-10-24T13:42:08.142364+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"91f7acd1-010b-4d7b-b41c-c1af6b99c48b","code":"CGST-RULE-96A","source_type":"rule","title":"Export of goods or services under bond or Letter of Undertaking","provision":"Rule 96A","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"A registered person may export or supply to SEZ without payment of IGST under a bond or LUT (Form GST RFD-11), undertaking to pay tax with interest if goods are not exported within three months of the invoice date (or extended period), or if payment for services is not received in convertible foreign exchange or INR as permitted by RBI within one year (or extended period).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.145035+00:00","updated_at":"2026-10-24T13:42:08.145035+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"06dcdf6d-673e-4664-b25d-2a5417d2d2a8","code":"CGST-RULE-138","source_type":"rule","title":"E-way bill","provision":"Rule 138","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"summary":"An e-way bill must be generated before movement of goods of consignment value exceeding Rs 50,000 (subject to exemptions in sub-rule (14) and State-specific thresholds for intra-State movement), with Part B containing vehicle details; validity is based on distance and may be extended, and an e-way bill may be cancelled within 24 hours if goods are not transported.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.147068+00:00","updated_at":"2026-10-24T13:42:08.147068+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"6a02a165-641d-4e4e-ba8a-56baaf752724","code":"CGST-RULE-138A","source_type":"rule","title":"Documents and devices to be carried by person-in-charge of conveyance","provision":"Rule 138A","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2018-04-01","effective_to":null,"applicable_fys":[],"summary":"The person in charge of a conveyance must carry the invoice, bill of supply or delivery challan and a copy of the e-way bill (physical or mapped to RFID); an IRN may be produced in lieu of the invoice for e-invoiced documents.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.149643+00:00","updated_at":"2026-10-24T13:42:08.149643+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"52685336-f452-4f36-916a-afda1ec1a125","code":"CGST-RULE-142","source_type":"rule","title":"Notice and order for demand; voluntary payment","provision":"Rule 142","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Prescribes pre-SCN intimation (DRC-01A), show cause notice summary (DRC-01), voluntary payment of tax, interest and penalty (DRC-03), reply (DRC-06) and order summary (DRC-07).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.152007+00:00","updated_at":"2026-10-24T13:42:08.152007+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"37ad82d7-63d3-4e11-ab13-52c33f9d89ec","code":"IGST-ACT-S2-6","source_type":"act","title":"Export of services","provision":"Section 2(6)","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Supply of service is export where the supplier is in India, the recipient is outside India, the place of supply is outside India, payment is received in convertible foreign exchange or in INR wherever permitted by RBI, and supplier and recipient are not merely establishments of a distinct person.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.153238+00:00","updated_at":"2026-10-24T13:42:08.153238+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"89b6e492-3638-43d5-9c14-0d41a45f3f84","code":"IGST-ACT-S2-11","source_type":"act","title":"Import of services","provision":"Section 2(11)","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Supply of service is import where the supplier is located outside India, the recipient is located in India and the place of supply is in India.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.155096+00:00","updated_at":"2026-10-24T13:42:08.155096+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"b93a5e1b-c18d-4eb4-a9c7-e54a443790d0","code":"IGST-ACT-S5-3","source_type":"act","title":"Reverse charge on notified inter-State supplies","provision":"Section 5(3)","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"IGST on notified categories of supply of goods or services is payable by the recipient on reverse charge basis; import of services by a person in the taxable territory is notified under this provision.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.156643+00:00","updated_at":"2026-10-24T13:42:08.156643+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"ace87534-4506-4a11-98b2-096b5d30b326","code":"IGST-ACT-S7-5","source_type":"act","title":"Inter-State supply including supply to SEZ","provision":"Section 7(5)","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Supply of goods or services when the supplier is in India and place of supply is outside India, supply to or by a SEZ developer or SEZ unit, and other specified supplies are treated as inter-State supplies.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.157962+00:00","updated_at":"2026-10-24T13:42:08.157962+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"e37d114c-24e5-4f9c-b9c9-d136a569e97e","code":"IGST-ACT-S10","source_type":"act","title":"Place of supply of goods (other than imports/exports)","provision":"Section 10","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Place of supply is where movement of goods terminates for delivery; in bill-to-ship-to transactions it is the principal place of business of the person on whose direction goods are delivered.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.159338+00:00","updated_at":"2026-10-24T13:42:08.159338+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"9536735c-e1b0-4432-9fa8-18ff17899686","code":"IGST-ACT-S12","source_type":"act","title":"Place of supply of services where supplier and recipient are in India","provision":"Section 12","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Generally the location of a registered recipient; specific rules apply for immovable property, restaurant, training, events, transportation, telecom, banking and other services.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.160932+00:00","updated_at":"2026-10-24T13:42:08.160932+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"439af45b-bde8-41a5-a896-a8ca8a358571","code":"IGST-ACT-S13","source_type":"act","title":"Place of supply of services where supplier or recipient is outside India","provision":"Section 13","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Default place of supply is the location of the recipient, with exceptions for performance-based services on goods, immovable property, events, intermediary services (location of supplier), and specified other services.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.162121+00:00","updated_at":"2026-10-24T13:42:08.162121+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"1c74a908-fa3c-4bb7-b803-979eb5a886da","code":"IGST-ACT-S16","source_type":"act","title":"Zero-rated supply","provision":"Section 16","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Export of goods or services and supplies to SEZ developers or units for authorised operations are zero-rated; ITC is available and refund may be claimed either by supplying under bond/LUT without payment of IGST or by paying IGST and claiming refund, subject to conditions.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.164036+00:00","updated_at":"2026-10-24T13:42:08.164036+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"0c6fe033-aaec-4b17-8afb-bc6e22a81ccd","code":"IGST-ACT-S19","source_type":"act","title":"Tax wrongfully collected and paid to Central or State Government","provision":"Section 19","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Where IGST has been paid on a supply subsequently held to be intra-State, the IGST paid is refunded and no interest is payable on CGST/SGST due under the correct head.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.166438+00:00","updated_at":"2026-10-24T13:42:08.166438+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"6ef025df-a531-41fc-bc43-f63bc4ac2e54","code":"CUSTOMS-ACT-S14","source_type":"act","title":"Valuation of goods","provision":"Section 14","statute":"Customs Act, 1962","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Value of imported and export goods is the transaction value, including specified costs, where buyer and seller are not related or relationship has not influenced the price, read with the Customs Valuation Rules.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.168606+00:00","updated_at":"2026-10-24T13:42:08.168606+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"b0f9d8cd-7e24-4644-9365-19134b5d2e69","code":"CUSTOMS-ACT-S17","source_type":"act","title":"Assessment of duty","provision":"Section 17","statute":"Customs Act, 1962","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Importers and exporters self-assess duty; the proper officer may verify and re-assess, and must pass a speaking order where re-assessment is contrary to the self-assessment and not accepted by the importer.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.170838+00:00","updated_at":"2026-10-24T13:42:08.170838+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"eec11c9e-6956-41c4-882e-e7de0c30ca89","code":"CUSTOMS-ACT-S18","source_type":"act","title":"Provisional assessment of duty","provision":"Section 18","statute":"Customs Act, 1962","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Duty may be provisionally assessed against security where documents or tests are pending; on finalisation, differential duty is payable with interest or refund is granted.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.172987+00:00","updated_at":"2026-10-24T13:42:08.172987+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"8688b887-8230-4752-b00e-21110f95a3f1","code":"CUSTOMS-ACT-S27","source_type":"act","title":"Claim for refund of duty","provision":"Section 27","statute":"Customs Act, 1962","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Refund of duty or interest is claimed within one year from the date of payment or relevant date, subject to unjust enrichment; the limitation does not apply where duty has been paid under protest.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.174921+00:00","updated_at":"2026-10-24T13:42:08.174921+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"768c0c68-649a-4054-bd65-940cd97bd794","code":"CUSTOMS-ACT-S28","source_type":"act","title":"Recovery of duties not levied, short-levied or erroneously refunded","provision":"Section 28","statute":"Customs Act, 1962","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Demand of duty not levied or short-levied may be raised within two years (five years in cases of collusion, wilful misstatement or suppression) from the relevant date.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.176689+00:00","updated_at":"2026-10-24T13:42:08.176689+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"fcfc5b29-eba2-4a6c-bcdf-2f4752712b6b","code":"CUSTOMS-ACT-S28AA","source_type":"act","title":"Interest on delayed payment of duty","provision":"Section 28AA","statute":"Customs Act, 1962","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Interest at the notified rate is payable on duty not paid or short-paid, in addition to the duty, from the date it was payable until payment.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.178846+00:00","updated_at":"2026-10-24T13:42:08.178846+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"e85e89a2-7129-49b6-93ce-34221328b73f","code":"CUSTOMS-ACT-S46","source_type":"act","title":"Entry of goods on importation (Bill of Entry)","provision":"Section 46","statute":"Customs Act, 1962","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Importer shall present a bill of entry for home consumption or warehousing electronically on ICEGATE within the prescribed time, declaring truthful contents and supported by invoices.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.180755+00:00","updated_at":"2026-10-24T13:42:08.180755+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"bccf82e1-2680-46b6-b797-ae4e252e1d44","code":"CUSTOMS-ACT-S50","source_type":"act","title":"Entry of goods for exportation (Shipping Bill)","provision":"Section 50","statute":"Customs Act, 1962","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Exporter shall present a shipping bill electronically on ICEGATE making truthful declarations and ensuring accuracy and completeness of information.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.182219+00:00","updated_at":"2026-10-24T13:42:08.182219+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"632f00a0-6b40-4bd5-b96a-545098446a1b","code":"CUSTOMS-ACT-S65","source_type":"act","title":"Manufacture and other operations in warehouse","provision":"Section 65","statute":"Customs Act, 1962","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Permits manufacturing and other operations in a customs bonded warehouse with permission, with import duty deferred on inputs and capital goods (MOOWR scheme); duty is payable on clearance for home consumption, while export clearances are duty-free.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.183957+00:00","updated_at":"2026-10-24T13:42:08.183957+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"8e6cc394-39fe-43a5-815f-793f0125c2b8","code":"CUSTOMS-ACT-S149","source_type":"act","title":"Amendment of documents","provision":"Section 149","statute":"Customs Act, 1962","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"The proper officer may permit amendment of a bill of entry or shipping bill after presentation; amendment after clearance or export is permissible only on documentary evidence existing at the time of import/export.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.185776+00:00","updated_at":"2026-10-24T13:42:08.185776+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"6364b976-d4b6-473a-8ef7-d7b8321505f1","code":"CUSTOMS-TARIFF-S3-7","source_type":"act","title":"IGST on imported goods","provision":"Section 3(7)","statute":"Customs Tariff Act, 1975","jurisdiction":"customs","source_url":"https://www.cbic.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Imported goods are liable to integrated tax at the rate leviable under the IGST Act on like goods, on the value including assessable value and customs duties (excluding IGST and compensation cess); this IGST is creditable as ITC on the basis of the bill of entry.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.189652+00:00","updated_at":"2026-10-24T13:42:08.189652+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d3a6fc1b-026a-4a68-ba4f-df1e8d8d3c72","code":"NOTIF-1-2017-CTR","source_type":"notification","title":"CGST rates on goods","provision":"Notification No. 1/2017-Central Tax (Rate)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"1/2017-Central Tax (Rate)","publication_date":"2017-06-28","effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Prescribes CGST rates on goods by HSN in schedules, as amended from time to time; read with corresponding SGST and IGST rate notifications.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.191782+00:00","updated_at":"2026-10-24T13:42:08.191782+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"13c44fe4-df35-40ce-8807-504aa73264d9","code":"NOTIF-4-2017-CTR","source_type":"notification","title":"Reverse charge on notified goods","provision":"Notification No. 4/2017-Central Tax (Rate)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"4/2017-Central Tax (Rate)","publication_date":"2017-06-28","effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Notifies goods on which tax is payable by the recipient under Section 9(3), such as specified cashew nuts, tendu leaves, tobacco leaves, silk yarn, and certain supplies by specified persons, as amended.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.194824+00:00","updated_at":"2026-10-24T13:42:08.194824+00:00"}') on conflict do nothing;
