insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"bbe0e620-ae24-4473-9a82-e9b44d39c2bd","code":"NOTIF-12-2017-CTR","source_type":"notification","title":"Exemption of specified services","provision":"Notification No. 12/2017-Central Tax (Rate)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"12/2017-Central Tax (Rate)","publication_date":"2017-06-28","effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Exempts specified services from CGST, including services by way of transfer of a going concern as a whole or an independent part thereof, as amended.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.199397+00:00","updated_at":"2026-10-24T13:42:08.199397+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"91ac386c-17ee-4297-a9f5-6e6875bbce17","code":"NOTIF-13-2017-CTR","source_type":"notification","title":"Reverse charge on notified services","provision":"Notification No. 13/2017-Central Tax (Rate)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"13/2017-Central Tax (Rate)","publication_date":"2017-06-28","effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Notifies services on which tax is payable by the recipient under Section 9(3), including GTA (where forward charge not opted), legal services by advocates, sponsorship, services by directors to the company, security services by non-body corporates, renting of motor vehicles in specified cases, and (from 10.10.2024) renting of commercial property by an unregistered person to a registered person, as amended.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.201053+00:00","updated_at":"2026-10-24T13:42:08.201053+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d0ed6bf5-9cda-4d79-8db2-04b694106d38","code":"NOTIF-10-2017-ITR","source_type":"notification","title":"IGST reverse charge on notified services including import of services","provision":"Notification No. 10/2017-Integrated Tax (Rate)","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":"https://cbic-gst.gov.in/","notification_no":"10/2017-Integrated Tax (Rate)","publication_date":"2017-06-28","effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Notifies inter-State services taxable under reverse charge under Section 5(3) of the IGST Act, including services supplied by a person located in a non-taxable territory to a person in the taxable territory (other than non-taxable online recipients), as amended.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.202598+00:00","updated_at":"2026-10-24T13:42:08.202598+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"7bbfe147-3785-4e81-87e4-21cda7a88035","code":"NOTIF-40-2017-CTR","source_type":"notification","title":"Concessional rate for supplies to merchant exporters","provision":"Notification No. 40/2017-Central Tax (Rate)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"40/2017-Central Tax (Rate)","publication_date":"2017-10-23","effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Prescribes a concessional CGST rate on intra-State supply of goods to registered merchant exporters, subject to conditions including export within 90 days, registration with an export promotion council, and movement directly to port or registered warehouse.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.204648+00:00","updated_at":"2026-10-24T13:42:08.204648+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"bdc29ab2-82fc-43bb-bb51-bf7c2663f8e9","code":"NOTIF-48-2017-CT","source_type":"notification","title":"Deemed exports","provision":"Notification No. 48/2017-Central Tax","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"48/2017-Central Tax","publication_date":"2017-10-18","effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Notifies supplies treated as deemed exports under Section 147, including supply against Advance Authorisation, supply of capital goods against EPCG authorisation, supply to EOUs, and supply of gold by banks against Advance Authorisation; refund may be claimed by recipient or supplier subject to conditions.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.206504+00:00","updated_at":"2026-10-24T13:42:08.206504+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"dcf1e8ea-4c8a-476d-8fae-571883a8edd0","code":"NOTIF-EINV-THRESHOLD","source_type":"notification","title":"E-invoicing applicability threshold","provision":"Notifications under Rule 48(4) (as amended)","statute":"Central Goods and Services Tax Rules, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2020-10-01","effective_to":null,"applicable_fys":[],"summary":"E-invoicing under Rule 48(4) applies to registered persons whose aggregate turnover in any financial year from 2017-18 onwards exceeds the notified threshold, progressively reduced from Rs 500 crore (01.10.2020) to Rs 5 crore (01.08.2023), with specified exempt classes such as SEZ units, insurers, banking companies, GTA and passenger transport service providers.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.208493+00:00","updated_at":"2026-10-24T13:42:08.208493+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"e2df07d1-6804-40d3-b642-d18551893842","code":"CIRC-92-11-2019","source_type":"circular","title":"Treatment of sales promotion schemes","provision":"Circular No. 92/11/2019-GST","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"92/11/2019-GST","publication_date":"2019-03-07","effective_from":"2019-03-07","effective_to":null,"applicable_fys":[],"summary":"Clarifies that free samples and gifts without consideration are not supply (except where covered by Schedule I) and ITC on them is blocked under Section 17(5)(h); in buy-one-get-one offers the free item is part of a composite or mixed supply and ITC is available; discounts in the invoice and pre-agreed volume discounts are excluded from value.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.21039+00:00","updated_at":"2026-10-24T13:42:08.21039+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"d53df042-deb1-466c-af41-71516d697a6e","code":"CIRC-170-02-2022","source_type":"circular","title":"Reporting of ITC availed, reversed and ineligible in GSTR-3B","provision":"Circular No. 170/02/2022-GST","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"170/02/2022-GST","publication_date":"2022-07-06","effective_from":"2022-07-06","effective_to":null,"applicable_fys":[],"summary":"Clarifies reporting in GSTR-3B Table 4: ITC per GSTR-2B to be reported in 4(A), permanent reversals (Rule 38, 42, 43, Section 17(5)) in 4(B)(1), temporary reversals (Rule 37, 37A, Section 16(2)(b)/(c)) in 4(B)(2) with re-claim in 4(A)(5) and 4(D)(1); and reporting of inter-State supplies to unregistered persons in Table 3.2.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.212545+00:00","updated_at":"2026-10-24T13:42:08.212545+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"1dfc189d-bd7e-4acc-bdda-849466af454f","code":"CIRC-172-04-2022","source_type":"circular","title":"Clarification on miscellaneous issues including perquisites and Section 17(5)","provision":"Circular No. 172/04/2022-GST","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"172/04/2022-GST","publication_date":"2022-07-06","effective_from":"2022-07-06","effective_to":null,"applicable_fys":[],"summary":"Clarifies, inter alia, that perquisites provided by employer to employee under the contract of employment are not supply, and that the proviso to Section 17(5)(b) (credit allowed where obligatory under any law) applies to the whole of clause (b).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.214342+00:00","updated_at":"2026-10-24T13:42:08.214342+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"f8b493bc-9e1e-4ecd-8afe-f229310716d1","code":"CIRC-183-15-2022","source_type":"circular","title":"Mismatch between ITC in GSTR-3B and GSTR-2A for FY 2017-18 and 2018-19","provision":"Circular No. 183/15/2022-GST","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"183/15/2022-GST","publication_date":"2022-12-27","effective_from":"2022-12-27","effective_to":null,"applicable_fys":[],"summary":"Prescribes the procedure for verifying ITC claims for FY 2017-18 and 2018-19 where invoices are not reflected in GSTR-2A, including CA/CMA certificates (above a threshold) or supplier certificates confirming supply and payment of tax.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.215969+00:00","updated_at":"2026-10-24T13:42:08.215969+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"bed18002-2f5d-435a-b5a2-6b4e0fe06695","code":"CIRC-195-07-2023","source_type":"circular","title":"Replacement of parts and repair services under warranty","provision":"Circular No. 195/07/2023-GST","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"195/07/2023-GST","publication_date":"2023-07-17","effective_from":"2023-07-17","effective_to":null,"applicable_fys":[],"summary":"Clarifies that replacement of parts or repair services by the manufacturer without consideration during the warranty period is not taxable and no ITC reversal is required by the manufacturer; it also addresses distributor replacements and extended warranties.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.218153+00:00","updated_at":"2026-10-24T13:42:08.218153+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"3afeeb22-5eea-4c7e-8584-ab879c165952","code":"CIRC-199-11-2023","source_type":"circular","title":"Taxability of services between distinct persons and ISD","provision":"Circular No. 199/11/2023-GST","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"199/11/2023-GST","publication_date":"2023-07-17","effective_from":"2023-07-17","effective_to":null,"applicable_fys":[],"summary":"Clarifies that for common input services procured from third parties, HO may distribute credit through ISD or cross-charge; where the recipient branch is eligible for full ITC, the value declared in the invoice is deemed open market value (including nil), and salary cost of HO employees need not be included in cross-charge value.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.221425+00:00","updated_at":"2026-10-24T13:42:08.221425+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"07db17c3-9abd-4b10-b701-65ffaa1081a8","code":"CIRC-210-04-2024","source_type":"circular","title":"Valuation of import of services from related persons","provision":"Circular No. 210/4/2024-GST","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"210/4/2024-GST","publication_date":"2024-06-26","effective_from":"2024-06-26","effective_to":null,"applicable_fys":[],"summary":"Clarifies that where a foreign related person supplies services to an Indian related person eligible for full ITC, the value declared in the invoice may be deemed open market value, and where no invoice is issued the value may be deemed nil, under the second proviso to Rule 28(1).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.222871+00:00","updated_at":"2026-10-24T13:42:08.222871+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"1b1218d9-ecf0-4f83-98a4-47b9430cbe91","code":"CIRC-211-05-2024","source_type":"circular","title":"Time limit under Section 16(4) for reverse charge supplies","provision":"Circular No. 211/5/2024-GST","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"211/5/2024-GST","publication_date":"2024-06-26","effective_from":"2024-06-26","effective_to":null,"applicable_fys":[],"summary":"Clarifies that for supplies from unregistered persons under reverse charge, the financial year relevant for the Section 16(4) time limit is the year in which the recipient issues the self-invoice under Section 31(3)(f), while noting that delayed self-invoicing attracts interest and penalty.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.224356+00:00","updated_at":"2026-10-24T13:42:08.224356+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"fd955a3c-bb2a-4512-b4c6-41b845377251","code":"CIRC-212-06-2024","source_type":"circular","title":"Compliance with Section 15(3)(b)(ii) for post-supply discounts","provision":"Circular No. 212/6/2024-GST","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":"https://cbic-gst.gov.in/","notification_no":"212/6/2024-GST","publication_date":"2024-06-26","effective_from":"2024-06-26","effective_to":null,"applicable_fys":[],"summary":"Prescribes the mechanism for suppliers to establish that recipients have reversed ITC attributable to post-supply discounts: certificate from the recipient (or CA/CMA certificate above a threshold) confirming reversal, in addition to the general route of verifying credit note acceptance on the portal.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.225902+00:00","updated_at":"2026-10-24T13:42:08.225902+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"0bba4996-b303-496b-85bb-71b7021b77a2","code":"ADV-IMS","source_type":"advisory","title":"Invoice Management System (IMS)","provision":"GSTN advisory","statute":"GST Network portal advisory","jurisdiction":"central","source_url":"https://www.gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2024-10-01","effective_to":null,"applicable_fys":[],"summary":"IMS allows recipients to accept, reject or keep pending invoices and other records uploaded by suppliers before generation of GSTR-2B, starting with records for the October 2024 tax period; rejected records do not flow to GSTR-2B and accepted/deemed-accepted records do.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.227076+00:00","updated_at":"2026-10-24T13:42:08.227076+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"8228b431-67c0-46a2-b449-86280d4eef17","code":"ADV-EINV-30DAY","source_type":"advisory","title":"Time limit for reporting e-invoices on IRP","provision":"GSTN advisory","statute":"GST Network portal advisory","jurisdiction":"central","source_url":"https://www.gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2023-11-01","effective_to":null,"applicable_fys":[],"summary":"GSTN advisories restrict generation of IRN for invoices and credit/debit notes older than 30 days from the date of reporting for notified classes of taxpayers by AATO (initially Rs 100 crore and above from 01.11.2023, later extended to Rs 10 crore and above).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.229887+00:00","updated_at":"2026-10-24T13:42:08.229887+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"35cde1da-458b-4aee-8238-c4d5481c4ded","code":"ADV-EXPORT-ICEGATE","source_type":"advisory","title":"Transmission of GSTR-1 Table 6A to ICEGATE for IGST refund","provision":"GSTN advisory","statute":"GST Network portal advisory","jurisdiction":"central","source_url":"https://www.gst.gov.in/","notification_no":null,"publication_date":null,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"summary":"Export invoice details furnished in GSTR-1 Table 6A, with shipping bill number, date and port code, are transmitted to ICEGATE and validated against the shipping bill and EGM; mismatches result in error responses that block the automated IGST refund until corrected (including through Table 9A amendments or officer intervention).","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.23211+00:00","updated_at":"2026-10-24T13:42:08.23211+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"9188a9e2-8cf2-43b6-9c6a-ebc38fa014b2","code":"JUDG-SAFARI-RETREATS-2024","source_type":"judgment","title":"Chief Commissioner of CGST v. Safari Retreats Pvt Ltd (Supreme Court, 2024)","provision":"Section 17(5)(d)","statute":"Central Goods and Services Tax Act, 2017","jurisdiction":"central","source_url":null,"notification_no":null,"publication_date":"2024-10-03","effective_from":"2024-10-03","effective_to":null,"applicable_fys":[],"summary":"The Supreme Court held that whether a building is a ''plant or machinery'' under Section 17(5)(d) is a functionality test to be applied on facts. Parliament subsequently amended Section 17(5)(d) retrospectively to read ''plant and machinery''; the position must be evaluated with the amended provision.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.234397+00:00","updated_at":"2026-10-24T13:42:08.234397+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"1e054a0b-906b-4ca1-901b-b360ff604c82","code":"JUDG-MOHIT-MINERALS-2022","source_type":"judgment","title":"Union of India v. Mohit Minerals Pvt Ltd (Supreme Court, 2022)","provision":"IGST reverse charge on ocean freight","statute":"Integrated Goods and Services Tax Act, 2017","jurisdiction":"igst","source_url":null,"notification_no":null,"publication_date":"2022-05-19","effective_from":"2022-05-19","effective_to":null,"applicable_fys":[],"summary":"The Supreme Court held that levy of IGST under reverse charge on ocean freight for CIF imports, where the importer is not the recipient of the transport service and IGST is already paid on the CIF value of goods, is unsustainable as a composite supply already taxed.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.237181+00:00","updated_at":"2026-10-24T13:42:08.237181+00:00"}') on conflict do nothing;
insert into public.legal_references select * from json_populate_record(null::public.legal_references, '{"id":"2539b157-2680-483e-9d09-8eb2d36a7fc2","code":"JUDG-NORTHERN-OPERATING-2022","source_type":"judgment","title":"CCE v. Northern Operating Systems Pvt Ltd (Supreme Court, 2022)","provision":"Secondment of employees by overseas group entity","statute":"Finance Act, 1994 (service tax); principles applied in GST","jurisdiction":"central","source_url":null,"notification_no":null,"publication_date":"2022-05-19","effective_from":"2022-05-19","effective_to":null,"applicable_fys":[],"summary":"The Supreme Court held that secondment of employees by an overseas group company to the Indian entity, with salary cost reimbursed, constituted supply of manpower service by the overseas entity taxable in the hands of the Indian recipient under reverse charge, depending on the facts of the arrangement.","amendment_history":[],"legal_status":"effective","verification_status":"unverified","verified_at":null,"verified_by":null,"approval_status":"pending","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.238901+00:00","updated_at":"2026-10-24T13:42:08.238901+00:00"}') on conflict do nothing;
