insert into public.control_versions select * from json_populate_record(null::public.control_versions, E'{"id":"fdecdd16-5f18-4507-bcaa-b254a37c2a4e","control_id":"N-AR-002","version":1,"effective_from":"2017-07-01","effective_to":null,"applicable_fys":[],"taxpayer_classes":[],"objective":"Analyse differences between ITC available as per 2B/2A and ITC availed for the year, including credit lapsing.","law_refs":["CGST-ACT-S44","CGST-RULE-80","CGST-ACT-S16-4"],"required_data":["gstr9","gstr2b","gstr3b","purchase_register"],"procedure":"1. Compare Table 8A (auto) with 8B and 8C.\\n2. Explain 8D differences (ineligible, timing, not booked).\\n3. Identify credit available but not availed that lapses.","automation":null,"expected_result":"Differences explained.","exception_conditions":"Large unexplained 8D differences; eligible credit lapsing.","risk_level":"medium","exposure_basis":"Lapsed ITC (lost opportunity); scrutiny queries on excess claims.","evidence_required":["Table 8 analysis"],"corrective_action":"Document and claim eligible credit within time.","signoff_role":"audit_manager","status":"approved","approved_by":null,"approved_at":null,"created_by":null,"created_at":"2026-10-24T13:42:08.692175+00:00"}') on conflict do nothing;
